-- ==============================================================================
-- InterviewHub Complete Database Migration Script for Neon Database
-- Target Database: neondb (Neon Serverless PostgreSQL)
-- Generates all schema tables, constraints, indexes, sequences, and current data.
-- ==============================================================================

-- 1. USERS TABLE
CREATE TABLE IF NOT EXISTS users (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    role VARCHAR(50) NOT NULL DEFAULT 'USER',
    phone_number VARCHAR(50),
    profile_photo TEXT,
    reset_token VARCHAR(255),
    reset_token_expiry TIMESTAMP,
    last_login_at TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP
);

-- 2. COMPANIES TABLE
CREATE TABLE IF NOT EXISTS companies (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL UNIQUE,
    logo VARCHAR(255),
    website VARCHAR(255),
    description TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP
);

-- 3. INTERVIEW EXPERIENCES TABLE
CREATE TABLE IF NOT EXISTS interview_experiences (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL,
    company_id BIGINT NOT NULL,
    job_role VARCHAR(255) NOT NULL,
    experience_title VARCHAR(255) NOT NULL,
    description TEXT,
    overall_difficulty VARCHAR(50) NOT NULL,
    result VARCHAR(50) NOT NULL,
    years_of_experience DOUBLE PRECISION,
    base_salary DOUBLE PRECISION,
    stock_grant DOUBLE PRECISION,
    signing_bonus DOUBLE PRECISION,
    total_compensation DOUBLE PRECISION,
    currency VARCHAR(10) DEFAULT 'INR',
    job_level VARCHAR(50),
    offer_accepted BOOLEAN,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP,
    CONSTRAINT fk_exp_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_exp_company FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_exp_company_id ON interview_experiences(company_id);
CREATE INDEX IF NOT EXISTS idx_exp_user_id ON interview_experiences(user_id);
CREATE INDEX IF NOT EXISTS idx_exp_difficulty ON interview_experiences(overall_difficulty);
CREATE INDEX IF NOT EXISTS idx_exp_created_at ON interview_experiences(created_at);

-- 4. INTERVIEW ROUNDS TABLE
CREATE TABLE IF NOT EXISTS interview_rounds (
    id BIGSERIAL PRIMARY KEY,
    experience_id BIGINT NOT NULL,
    round_name VARCHAR(255),
    round_number INT,
    round_type VARCHAR(50),
    description TEXT,
    difficulty VARCHAR(50),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP,
    CONSTRAINT fk_round_experience FOREIGN KEY (experience_id) REFERENCES interview_experiences(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_round_experience_id ON interview_rounds(experience_id);

-- 5. QUESTIONS TABLE
CREATE TABLE IF NOT EXISTS questions (
    id BIGSERIAL PRIMARY KEY,
    round_id BIGINT NOT NULL,
    question_text TEXT NOT NULL,
    question_type VARCHAR(50) NOT NULL,
    difficulty VARCHAR(50) NOT NULL,
    topic VARCHAR(255),
    answer TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP,
    CONSTRAINT fk_question_round FOREIGN KEY (round_id) REFERENCES interview_rounds(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_question_round_id ON questions(round_id);
CREATE INDEX IF NOT EXISTS idx_question_difficulty ON questions(difficulty);

-- 6. BOOKMARKS TABLE
CREATE TABLE IF NOT EXISTS bookmarks (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL,
    experience_id BIGINT NOT NULL,
    status VARCHAR(30) NOT NULL DEFAULT 'PLANNING',
    notes TEXT,
    target_date TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP,
    CONSTRAINT fk_bookmark_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_bookmark_experience FOREIGN KEY (experience_id) REFERENCES interview_experiences(id) ON DELETE CASCADE,
    CONSTRAINT uk_user_experience_bookmark UNIQUE (user_id, experience_id)
);
CREATE INDEX IF NOT EXISTS idx_bookmark_user_id ON bookmarks(user_id);
CREATE INDEX IF NOT EXISTS idx_bookmark_created_at ON bookmarks(created_at);

-- 7. CHAT MESSAGES TABLE
CREATE TABLE IF NOT EXISTS chat_messages (
    id BIGSERIAL PRIMARY KEY,
    sender_id BIGINT NOT NULL,
    sender_name VARCHAR(255) NOT NULL,
    sender_email VARCHAR(255) NOT NULL,
    receiver_id BIGINT NOT NULL,
    receiver_name VARCHAR(255) NOT NULL,
    receiver_email VARCHAR(255) NOT NULL,
    content TEXT NOT NULL,
    is_read BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_chat_sender_receiver ON chat_messages(sender_id, receiver_id);
CREATE INDEX IF NOT EXISTS idx_chat_receiver_read ON chat_messages(receiver_id, is_read);
CREATE INDEX IF NOT EXISTS idx_chat_created_at ON chat_messages(created_at);

