-- DATA FOR: interview_experiences
INSERT INTO interview_experiences (id, user_id, company_id, job_role, experience_level, interview_type, difficulty, result, description, advice, created_at, updated_at, experience_title, overall_difficulty, years_of_experience, base_salary, currency, job_level, offer_accepted, signing_bonus, stock_grant, total_compensation) VALUES (41, 5, 2, 'Software Engineer III (L4)', NULL, NULL, NULL, 'SELECTED', 'Recent 4-round virtual on-site interview loop for Google SWE III (L4) on the Core Storage & Search Infrastructure team. The process consisted of 2 heavy DSA rounds emphasizing graph shortest paths with dynamic fuel states and prefix tree autocomplete, 1 distributed systems design round on a distributed counter and real-time metrics aggregator handling 500k QPS, and 1 Googliness & Leadership behavioral round.', 'Always clarify edge cases and scale limits before writing any line of code. For Google DSA, focus on modular, idiomatic code with zero dead branches. For Googliness, prepare structured STAR stories showing data-driven consensus building and intellectual humility.', '2026-09-21 16:40:53.948375', '2026-09-21 16:40:53.948375', 'Google SWE III (L4) Core Infrastructure Interview Loop', 'HARD', 4.5, 165000.0, 'USD', 'L4', true, 20000.0, 55000.0, 240000.0) ON CONFLICT (id) DO NOTHING;
INSERT INTO interview_experiences (id, user_id, company_id, job_role, experience_level, interview_type, difficulty, result, description, advice, created_at, updated_at, experience_title, overall_difficulty, years_of_experience, base_salary, currency, job_level, offer_accepted, signing_bonus, stock_grant, total_compensation) VALUES (42, 7, 6, 'Software Engineer II', NULL, NULL, NULL, 'SELECTED', '4-round technical interview loop for Software Engineer II on Microsoft Azure Core Cloud Infrastructure (Hyderabad). Evaluated on Codility online assessment, concurrent low-level design of an asynchronous task orchestrator, high-level system design of a resumable chunked blob storage upload pipeline, and an engineering culture round with the Principal Director.', 'Master thread-safety and concurrency primitives (locks, semaphores, atomics). For Azure system design, explain how you mitigate partial network failures and transient errors using Polly circuit breakers and exponential backoff.', '2026-09-08 16:40:53.948375', '2026-09-08 16:40:53.948375', 'Microsoft Software Engineer II (L61) Azure Cloud & Distributed Systems Loop', 'MEDIUM', 3.5, 3200000.0, 'INR', 'Level 61', true, 400000.0, 1200000.0, 4800000.0) ON CONFLICT (id) DO NOTHING;
INSERT INTO interview_experiences (id, user_id, company_id, job_role, experience_level, interview_type, difficulty, result, description, advice, created_at, updated_at, experience_title, overall_difficulty, years_of_experience, base_salary, currency, job_level, offer_accepted, signing_bonus, stock_grant, total_compensation) VALUES (43, 40, 27, 'Software Engineer (P40)', NULL, NULL, NULL, 'SELECTED', 'Comprehensive 4-round interview loop for Atlassian Software Engineer (P40) on the Real-Time Jira Collaboration platform (Bengaluru). Heavy emphasis on clean code craftsmanship, code refactoring without breaking tests, real-time WebSocket notification fan-out architecture, and alignment with Atlassian core values.', 'Atlassian values clean, maintainable code over quick hacky algorithms. Write clean unit test assertions during coding and articulate SOLID design principles. For behavioral, read up on "Open Company, No Bullshit".', '2026-08-25 16:40:53.948375', '2026-08-25 16:40:53.948375', 'Atlassian Software Engineer (P40) Real-Time Jira Collaboration Loop', 'HARD', 4.0, 3600000.0, 'INR', 'P40 / SDE II', true, 450000.0, 1600000.0, 5650000.0) ON CONFLICT (id) DO NOTHING;
INSERT INTO interview_experiences (id, user_id, company_id, job_role, experience_level, interview_type, difficulty, result, description, advice, created_at, updated_at, experience_title, overall_difficulty, years_of_experience, base_salary, currency, job_level, offer_accepted, signing_bonus, stock_grant, total_compensation) VALUES (44, 7, 28, 'Senior Software Engineer (SDE II)', NULL, NULL, NULL, 'SELECTED', 'Intensive 4-round interview loop for Swiggy SDE II (Bengaluru) on the Core Logistics & Order Dispatch Platform. Spanned machine coding for a surge pricing and delivery partner dispatch algorithm in 90 minutes, dynamic programming algorithms, a high-throughput geospatial tracking architecture handling 200k RPS, and an engineering director culture fit round.', 'Practice 90-minute machine coding rounds with clean object-oriented class modeling and runnable unit tests. For Swiggy system design, master geospatial indexing (H3 / S2 / Geohash) and Kafka partitioning by geohash.', '2026-08-12 16:40:53.948375', '2026-08-12 16:40:53.948375', 'Swiggy Senior Software Engineer (SDE II) Hyperlocal Delivery Loop', 'HARD', 4.2, 3300000.0, 'INR', 'SDE II', true, 300000.0, 600000.0, 4200000.0) ON CONFLICT (id) DO NOTHING;
SELECT setval(pg_get_serial_sequence('interview_experiences', 'id'), COALESCE((SELECT MAX(id) FROM interview_experiences), 1));

