-- DATA FOR: questions
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (53, 63, 'Find the cheapest flight route between cities with at most K stops and a fuel tank capacity limit.', 'DSA', 'HARD', 'Model as a state-space graph where state is (city, remaining_fuel, stops). Use a PriorityQueue (Dijkstra) ordered by accumulated cost.', '2026-10-26 16:40:53.948375', 'Graphs / PriorityQueue', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (54, 64, 'Design a Trie data structure supporting insert(word, frequency) and topK(prefix, k) in sub-millisecond time.', 'DSA', 'MEDIUM', 'Each Trie node maintains a bounded Min-Heap or sorted top 5 suggestions list during insertion to achieve O(prefix_length) retrieval.', '2026-10-26 16:40:53.948375', 'Trie / Min-Heap', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (55, 65, 'Design a real-time counter and telemetry aggregator that can process 500,000 incoming events per second with 99th percentile latency under 20ms.', 'SYSTEM_DESIGN', 'HARD', 'Combine edge buffering (Envoy/Fluentbit), Kafka partitioned by metric ID, in-memory Redis cluster with probabilistic HyperLogLog, and ClickHouse for analytical queries.', '2026-10-26 16:40:53.948375', 'Distributed Systems', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (56, 66, 'Describe a situation where you had a disagreement with a Tech Lead regarding architectural direction.', 'BEHAVIORAL', 'MEDIUM', 'Presented benchmark data comparing latency under load, demonstrated empirical memory overhead, and established consensus.', '2026-10-26 16:40:53.948375', 'STAR Method', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (57, 67, 'Calculate the maximum diameter of a binary tree with weighted edge values.', 'DSA', 'MEDIUM', 'Post-order traversal calculating the maximum left and right depths while keeping a running global maximum of left + right.', '2026-10-26 16:40:53.948375', 'Trees / DFS', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (58, 68, 'Implement a thread-safe LRU Cache with O(1) read/write operations and TTL expiration in Java/C#.', 'LLD', 'HARD', 'Doubly Linked List + ConcurrentHashMap with ReadWriteLock or segmented striped locking, plus a background cleaner thread or lazy eviction on access.', '2026-10-26 16:40:53.948375', 'Concurrency / Data Structures', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (59, 69, 'How would you architect a global resumable chunk upload service for large files with unstable network connections?', 'SYSTEM_DESIGN', 'HARD', 'Break files into 8MB chunks, calculate SHA-256 block hashes, upload in parallel to pre-signed S3/Blob URLs, track upload state in DynamoDB/CosmosDB, and execute atomic block assembly.', '2026-10-26 16:40:53.948375', 'Cloud Architecture', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (60, 70, 'Describe a production outage you responded to and how you applied growth mindset principles to prevent recurrence.', 'BEHAVIORAL', 'MEDIUM', 'Immediate failover to hot standby, root-caused connection pool saturation during load spike, and introduced circuit breakers with dynamic rate limiting.', '2026-10-26 16:40:53.948375', 'STAR Method', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (61, 71, 'Find the maximum value in every sliding window of size K in an array of N integers in O(N) time.', 'DSA', 'HARD', 'Maintain a double-ended queue (Deque) storing indices in decreasing order of element values, removing out-of-window elements from the front and smaller elements from the back.', '2026-10-26 16:40:53.948375', 'Monotonic Queue', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (62, 72, 'Refactor a tightly coupled 300-line monolithic class handling payment, invoice generation, and email dispatch into decoupled modules.', 'CODING', 'HARD', 'Apply Dependency Inversion and Single Responsibility Principles. Extract PaymentGateway, InvoiceService, and NotificationSender interfaces, and add Mockito unit tests.', '2026-10-26 16:40:53.948375', 'Clean Code / SOLID', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (63, 73, 'Design the backend notification service for Jira when users are @mentioned in comments across tickets.', 'SYSTEM_DESIGN', 'HARD', 'Use Kafka event topic for issue_comments, parse @mentions via regex, publish to user_notification worker pool, write to Cassandra notification feed, and push via WebSocket gateway to online clients.', '2026-10-26 16:40:53.948375', 'Event Driven Architecture', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (64, 74, 'Tell me about a time you noticed a project was heading in the wrong direction and spoke up candidly.', 'BEHAVIORAL', 'MEDIUM', 'Identified design flaw in data synchronization model early, gathered team for open technical review, and proposed event-driven alternative that avoided 2 months of rework.', '2026-10-26 16:40:53.948375', 'STAR Method', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (65, 75, 'Implement a delivery partner assignment service with criteria: shortest distance, partner rating, and active order load.', 'MACHINE_CODING', 'HARD', 'Use Strategy pattern for AssignmentStrategy (DistanceStrategy, RatingStrategy), Geohash spatial index for candidate discovery, and synchronized locking to prevent double-assignment.', '2026-10-26 16:40:53.948375', 'OOP / Strategy Pattern', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (66, 76, 'Given a courier with multiple pickup and delivery locations, find the minimum total travel time such that every pickup occurs before its corresponding delivery.', 'DSA', 'HARD', 'Bitmask DP on visited states or branch-and-bound graph traversal respecting topological precedence constraints.', '2026-10-26 16:40:53.948375', 'Dynamic Programming / Bitmask', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (67, 77, 'How would you ingest and query GPS coordinates of 300,000 delivery partners sending updates every 3 seconds (100k+ RPS)?', 'SYSTEM_DESIGN', 'HARD', 'Ingest via Netty/gRPC gateway, push to Kafka partitioned by Geohash/H3 cell, write to Redis Geospatial (GEOADD) in memory with 30s TTL, and asynchronous batch dump to Cassandra for historical route replay.', '2026-10-26 16:40:53.948375', 'Geospatial Architecture', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, round_id, question_text, question_type, difficulty, answer, created_at, topic, updated_at) VALUES (68, 78, 'Describe an experience where an unexpected surge traffic crippled order processing. How did you stabilize it and what were your long-term mitigations?', 'BEHAVIORAL', 'MEDIUM', 'Activated graceful degradation disabling non-critical recommendations, increased Kafka partition consumers, and implemented geohash-based rate throttling.', '2026-10-26 16:40:53.948375', 'STAR Method', '2026-10-26 16:40:53.948375') ON CONFLICT (id) DO NOTHING;
SELECT setval(pg_get_serial_sequence('questions', 'id'), COALESCE((SELECT MAX(id) FROM questions), 1));

